create table if not exists workflow_templates(id text primary key,tenant_id text not null,key text not null,name text not null,stages jsonb not null default '[]',rules jsonb not null default '{}',active boolean not null default true,version int not null default 1,updated_by text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,key));